mapper.select:
SELECT ae.id AS id, ae.paper_id AS paperId, p.paper_title AS paperTitle, ae.student_id AS studentId, su.real_name AS studentName, ae.teacher_id AS teacherId, tu.real_name AS teacherName, p.college_id AS collegeId, c.college_name AS collegeName, ae.score_timeliness AS scoreTimeliness, ae.score_quality AS scoreQuality, ae.score_attitude AS scoreAttitude, ae.score_professional AS scoreProfessional, ae.score_overall AS scoreOverall, ae.tags AS tagsJson, ae.comment AS comment, ae.create_time AS createTime FROM advisor_evaluation ae LEFT JOIN paper_info p ON ae.paper_id = p.id LEFT JOIN sys_user su ON ae.student_id = su.id LEFT JOIN sys_user tu ON ae.teacher_id = tu.id LEFT JOIN college c ON p.college_id = c.id WHERE ae.is_deleted = 0
AND ae.teacher_id = #{req.teacherId}
AND p.college_id = #{req.collegeId}
AND ae.score_overall >= #{req.minOverall}
AND ae.score_overall <= #{req.maxOverall}
ORDER BY ae.create_time DESC, ae.id DESC
